import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"大有","description":"焦氏易林注 - 大有","frontmatter":{"title":"大有","description":"焦氏易林注 - 大有"},"headers":[],"relativePath":"classics/jiaoyilin/014.md","filePath":"classics/jiaoyilin/014.md"}'),l={name:"classics/jiaoyilin/014.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大有" tabindex="-1">大有 <a class="header-anchor" href="#大有" aria-label="Permalink to “大有”">​</a></h1><h3 id="大有-1" tabindex="-1">大有 <a class="header-anchor" href="#大有-1" aria-label="Permalink to “大有”">​</a></h3><h3 id="大有之乾" tabindex="-1">大有之乾 <a class="header-anchor" href="#大有之乾" aria-label="Permalink to “大有之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>南山太行，困於空桑。老沙為石，牛馬無食。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《大有》象。乾為山、為行，位南，故曰南山。太行，亦山名也。伏坎為困，艮為桑，坤虛，故曰空桑。艮為沙石。坤為老、為牛馬，兌為食，坤閉，故曰無食。○無食，宋元本作無糧，依汲古。</p><h3 id="大有之坤" tabindex="-1">大有之坤 <a class="header-anchor" href="#大有之坤" aria-label="Permalink to “大有之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>播木折枝，與母別離，絕不相知。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>依《訟》之《謙》校。播，種也，言折枝種於他所，與母樹分離也。○宋元、汲古皆作&quot;蟠木失歧&quot;，誤。按：此亦用《大有》伏象。</p><h3 id="大有之屯" tabindex="-1">大有之屯 <a class="header-anchor" href="#大有之屯" aria-label="Permalink to “大有之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>噂噂所言，莫如我垣。歡樂堅固，可以長安。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《困》。○宋元本作譐譐，依汲古。莫如我垣，亦依汲古，宋元作&quot;莫知我恆&quot;，誤。</p><h3 id="大有之蒙" tabindex="-1">大有之蒙 <a class="header-anchor" href="#大有之蒙" aria-label="Permalink to “大有之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>雹梅零墜，心思憒憒。懷憂少愧，亂我魂氣。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為果、為梅，坎為冰，故曰雹梅。《爾雅》葖蘆萉註：紫花大根，俗呼雹突，由此例之，是雹梅為象形之字，作李者非也。坎折故零墜。坎為心思，坎憂故憒憒。坤為我、為亂、為魂氣。○憒憒，依宋元本，汲古作積憒。雹，各本作李，依《頤》之《否》校。</p><h3 id="大有之需" tabindex="-1">大有之需 <a class="header-anchor" href="#大有之需" aria-label="Permalink to “大有之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>火雖熾，在吾後。寇雖多，在吾右。身安吉，不危殆。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>離為火，伏坤為吾，在下故曰在後。坎為寇，兌為右，伏坤為身、為安。殆，音以。</p><h3 id="大有之訟" tabindex="-1">大有之訟 <a class="header-anchor" href="#大有之訟" aria-label="Permalink to “大有之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>虎臥山隅，鹿過後朐。弓矢設張，蝟為功曹，伏不敢起，遂至平原，得我美草。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為虎、為山，伏震為鹿、為後。《廣韻》：&quot;朐，山名&quot;，《史記始皇本紀》：&quot;立石上朐界中&quot;，由是例之，後朐或山名也。坎為弓矢、為棘、為蝟、為伏，伏坤為平野、為我。震為美草。○遂，依宋元本，汲古作逐。平，汲古、元本作洋，依宋本。坎為矢證。《後漢書百官志》：&quot;功曹主選署及眾事為郡吏長&quot;，《論衡》雲：&quot;人謂虎食人，功曹為姦所致。&quot;其意以為功曹為吏率虎為獸雄，而蝟能伏虎，故虎畏見。《史記龜策傳》註：蝟能伏虎。</p><h3 id="大有之師" tabindex="-1">大有之師 <a class="header-anchor" href="#大有之師" aria-label="Permalink to “大有之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>三火起明，雨滅其光。高位疾顛，驕恣誅傷。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>伏離為火，數三，故曰三火。坎為雨、為黑，故無光。坎為疾。坤為誅傷。○顛，宋元作巔，依汲古。誅，汲古作深，依宋元。</p><h3 id="大有之比" tabindex="-1">大有之比 <a class="header-anchor" href="#大有之比" aria-label="Permalink to “大有之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>疋居楚烏，遇讒無辜，久旅離憂。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>丁雲：&quot;疋，雅同&quot;，《說文》：&quot;雅，楚鳥也，一名鸒，一名卑居，秦謂之雅&quot;，言雅居楚即謂烏也。艮為烏，故曰烏、曰雅。坎上下兌口相背，故曰讒。坎為憂。○疋居楚烏，依汲古，宋元本作&quot;匹君楚馬&quot;，非。旅，依宋元，汲古作散。○艮烏確證。</p><h3 id="大有之小畜" tabindex="-1">大有之小畜 <a class="header-anchor" href="#大有之小畜" aria-label="Permalink to “大有之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>一室百子，同公異母。以義防患，禍災不起。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。坎為室，數一。坤為百，震為子、為公。坤為母，上下坤相背，故曰異母。坎為患，坤為禍災，坎伏，故不起。○百子、同公，依宋元本，汲古作十子、作同心，似非。</p><h3 id="大有之履" tabindex="-1">大有之履 <a class="header-anchor" href="#大有之履" aria-label="Permalink to “大有之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>商人行旅，資所無有。貪其利珠，流連王市。還家內顧，公子何咎。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為商旅、為行人、為珠，巽為利市，乾為王，故曰王市。艮為家，離為顧，震為公子。○所無，依宋元本，資所無有者，言資無所出也。汲古作&quot;資無所有&quot;，非。</p><h3 id="大有之泰" tabindex="-1">大有之泰 <a class="header-anchor" href="#大有之泰" aria-label="Permalink to “大有之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>禹將為君，北入昆侖。稍進揚光，登入溫湯。代舜為治，功德昭明。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾為君王，故曰禹。伏艮為昆侖。坤位北，艮陽在上為光，艮手，故曰揚光。坤水為湯，艮火，故曰溫湯。震為帝，故曰舜。○揚光，依宋元本，汲古作陽光，非。代舜為治，依宋元本增，汲古無。○坤北證。</p><h3 id="大有之否" tabindex="-1">大有之否 <a class="header-anchor" href="#大有之否" aria-label="Permalink to “大有之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>乾行天德，覆幬無極。嘔呼烹熟，使各自得。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為天，故覆幬無極，伏震兌，故曰嘔呼。艮火坤斧，故曰烹熟。○天，汲古作大，烹作享，均依宋元本。</p><h3 id="大有之同人" tabindex="-1">大有之同人 <a class="header-anchor" href="#大有之同人" aria-label="Permalink to “大有之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>南國盛茂，黍稷醴酒。可以享老，樂我嘉友。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為南，伏坤為國。震為盛茂、為黍稷，伏坎為酒。乾為老，震為樂。○盛茂，汲古作茂盛，醴作醲，均依宋元本。</p><h3 id="大有之大有" tabindex="-1">大有之大有 <a class="header-anchor" href="#大有之大有" aria-label="Permalink to “大有之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>白虎張牙，征伐東萊。朱雀前驅，贊道說辭。敵人請服，銜璧而趨。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>兌為虎、為牙，西方色白，故曰白虎張牙。白虎，西方宿。離為東，兌為決、為斧鉞，故曰征伐東萊。萊，汲古本作東華。按：《史記》雲：師尚父封於營邱，未至國，萊人來伐，爭營邱。營邱，邊萊。萊，夷人也。但太公徵萊今史不詳，不知華萊孰是，姑從宋元。朱雀，南方宿。離為雀，南方色赤，故曰朱雀。兌口，故曰贊道說辭。道導通。乾為玉，兌口故曰銜璧。○東萊，汲古本作東華，依宋元。</p><h3 id="大有之謙" tabindex="-1">大有之謙 <a class="header-anchor" href="#大有之謙" aria-label="Permalink to “大有之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>方船備水，傍河燃火，終身無禍。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為船，坤為船，坤為方，方，並也。《詩》&quot;方舟為梁&quot;，故可備水。坎水坎河，艮為火，故曰傍河燃火。坤為身、為禍，震喜，故無禍。○汲古多&quot;與夫吉昌，永得安康&quot;二句，依宋元本。</p><h3 id="大有之豫" tabindex="-1">大有之豫 <a class="header-anchor" href="#大有之豫" aria-label="Permalink to “大有之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>雷行相逐，無有休息。戰於平陸，為夷所覆。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《泰》。</p><h3 id="大有之隨" tabindex="-1">大有之隨 <a class="header-anchor" href="#大有之隨" aria-label="Permalink to “大有之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>躑躅踟躕，拊心搔頭。五晝四夜，睹我齊侯。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震足故躑躅、踟躕。坎為心、為首，艮手，故拊心搔頭。艮為日、為晝，兌為夜，震卦數四，巽五。巽為齊。○睹，依宋元本，汲古作賭。○上二句用《邶詩》註，詳《同人》之《隨》。</p><h3 id="大有之蠱" tabindex="-1">大有之蠱 <a class="header-anchor" href="#大有之蠱" aria-label="Permalink to “大有之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>大口宣唇，神使伸言。黃龍景星，出應德門。與福上堂，天下安昌。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《萃》。</p><h3 id="大有之臨" tabindex="-1">大有之臨 <a class="header-anchor" href="#大有之臨" aria-label="Permalink to “大有之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>陰衰老極，陽建其德。履離戴光，天下昭明。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《無妄》。第三句各本皆訛&quot;離載陽光&quot;，依《坤》之《未濟》校。</p><h3 id="大有之觀" tabindex="-1">大有之觀 <a class="header-anchor" href="#大有之觀" aria-label="Permalink to “大有之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>三塗五嶽，陽城太室。神明所伏，獨無兵革。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《蒙》，汲古多&quot;下有保國&quot;四字，依宋元本。</p><h3 id="大有之噬嗑" tabindex="-1">大有之噬嗑 <a class="header-anchor" href="#大有之噬嗑" aria-label="Permalink to “大有之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>年豐歲熟，政仁民樂。利以居止，旅人獲福。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為年歲、為豐熟、為仁樂，伏巽為利。艮為居止，震為旅人。○政仁，依宋元，汲古作仁政，非。</p><h3 id="大有之賁" tabindex="-1">大有之賁 <a class="header-anchor" href="#大有之賁" aria-label="Permalink to “大有之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>楚烏逢矢，不可久放。離居無群，意昧精喪。作此哀詩，以告孔憂。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>楚烏，即雅，見《說文》。艮為黔啄，故曰烏。震為叢木，故曰楚烏。坎為矢，故曰楚烏逢矢。艮為居，坎為孤，故曰離居無群。坎為心、為隱伏，故曰意昧。震神坎陷，故精喪。坎為哀憂，震為告。《詩四月篇》：&quot;君子作詩，維以告哀&quot;。○烏，從宋元本，汲古作鳥。矢，宋元本訛天，從汲古。可，宋元本作時，從汲古。群，汲古作辜，從宋元本。汲古無意昧精喪句。</p><h3 id="大有之剝" tabindex="-1">大有之剝 <a class="header-anchor" href="#大有之剝" aria-label="Permalink to “大有之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>出門大步，與兇惡忤。罵公詈母，為我憂恥。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為門戶、為兇、為母、為我憂。伏乾為行、為公，兌為罵詈。○兇，依宋元本，汲古作兄，非。恥，亦從宋元本，汲古作趾，非。</p><h3 id="大有之復" tabindex="-1">大有之復 <a class="header-anchor" href="#大有之復" aria-label="Permalink to “大有之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>火至井谷，陽芒生角。犯厯天市，窺觀太極。登上玉床，家易六公。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>天市，依汲古。《天官書》：&quot;旗中四星曰天市&quot;，宋元本作天戶，非。太極，依汲古，即北極也，宋元作太微，不韻。又陽宜作楊，古楊柳不分，即柳星也。按：此亦用《大有》象。離為星、為火，兌為井谷，伏艮為角，離為觀。太極謂五。乾為玉，伏艮為床。</p><h3 id="大有之無妄" tabindex="-1">大有之無妄 <a class="header-anchor" href="#大有之無妄" aria-label="Permalink to “大有之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>牧羊逢狼，雖憂不傷。畏怖惕息，終無禍殃。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為羊，震艮對，故曰逢狼。艮為狼，坤為牧、為憂傷，乾惕，故曰惕息。坤為禍殃，坤伏故無。○惕，依汲古，宋元本訛既。</p><h3 id="大有之大畜" tabindex="-1">大有之大畜 <a class="header-anchor" href="#大有之大畜" aria-label="Permalink to “大有之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>繭慄犧牲，敬事鬼神。神嗜飲食，受福多孫。望季不來，孔聖厄陳。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>上四句詳《乾》之《旅》。艮為季，艮止，故不來。乾為聖，震為孔、為陳。○鬼，宋元本作貴，神嗜作享者，茲依汲古。</p><h3 id="大有之頤" tabindex="-1">大有之頤 <a class="header-anchor" href="#大有之頤" aria-label="Permalink to “大有之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>大澤治妝，南歸牧羊。長伯為我，多得牛馬，利於徙居。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為水、為海，故曰大澤。妝，俗作娤，為裝之訛字。震為行，故治裝。伏兌為羊，坤為牧，震為歸、為南、為伯、為長。坤為我、為牛、為馬，震行故徙居。○大澤治妝，宋元本作大蓋治床，依汲古。歸羊，從宋元本。牧，從汲古。牛馬，依宋元本，汲古作馬牛。</p><h3 id="大有之大過" tabindex="-1">大有之大過 <a class="header-anchor" href="#大有之大過" aria-label="Permalink to “大有之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>枯樹無枝，與子分離。饑寒莫養，獨立哀悲。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。震為樹，互大離科上槁，故曰枯，巽寡故無枝。震為子，風散故分離。乾為寒，離虛為飢，坤死故莫養。坤為哀悲。</p><h3 id="大有之坎" tabindex="-1">大有之坎 <a class="header-anchor" href="#大有之坎" aria-label="Permalink to “大有之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>天地九重，堯舜履中。正冠垂裳，宇宙平康。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互震為帝，故曰堯舜。震為履，坎為中，艮為冠，坤為裳，坎為平。○履，汲古作治，依宋元本。</p><h3 id="大有之離" tabindex="-1">大有之離 <a class="header-anchor" href="#大有之離" aria-label="Permalink to “大有之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>鳧鷖遊涇，君子以寧。履德不衍，福祿來成。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏震為鳧鷖，坎為涇，艮為君子，震為履、為福祿。○涇，元本作滛，從宋本、汲古。履，從宋元本，汲古訛復。</p><h3 id="大有之鹹" tabindex="-1">大有之鹹 <a class="header-anchor" href="#大有之鹹" aria-label="Permalink to “大有之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>裸裎逐狐，為人觀笑。牝雞雄晨，主作亂根。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。坤為身，故曰裸裎。艮為狐，震為逐、為人、為笑，艮為觀，互巽為雞，震為雄、為旦、為鳴，故曰雄晨。震為主，坤為亂。○裸裎，宋元本作裸袒，依汲古。觀，汲古作所，雄作司，均依宋元本。《書》：牝雞之辰，惟家之索。</p><h3 id="大有之恆" tabindex="-1">大有之恆 <a class="header-anchor" href="#大有之恆" aria-label="Permalink to “大有之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>典冊法書，藏在蘭臺。雖遭亂潰，獨不遇災。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《大畜》。○書、亂，從宋元本，汲古作言、作禍，《論衡》：&quot;連山藏在蘭臺&quot;。</p><h3 id="大有之遯" tabindex="-1">大有之遯 <a class="header-anchor" href="#大有之遯" aria-label="Permalink to “大有之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>三痴且狂，欲之平鄉。迷惑失道，不知昏明。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>通《臨》。坤為痴，震數三，故曰三痴。震起故曰且狂。《詩鄭風》：&quot;不見子都，乃見狂且&quot;，《說文》：&quot;且，薦也，薦，進也&quot;，《集韻》：&quot;且，徂也&quot;，且狂，猶狂且也。坤為平鄉，震為之，坤為迷惑、為失，震為大塗，坤夜震旦，故曰昏明，坤迷故不知。全用對象。○且狂，依汲古，宋元本作俱，非。且，音徂。</p><h3 id="大有之大壯" tabindex="-1">大有之大壯 <a class="header-anchor" href="#大有之大壯" aria-label="Permalink to “大有之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>癭瘤瘍疥，為身瘡害。疾病癃痾，常不危殆。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。艮多節，故曰癭瘤瘍疥、曰癃痾。坤為身、為害、為疾病，艮安故不危殆。○害，依宋元本，汲古作患，不協。痾、危殆。皆依汲古，宋元本作痢、作屬逮，似非。</p><h3 id="大有之晉" tabindex="-1">大有之晉 <a class="header-anchor" href="#大有之晉" aria-label="Permalink to “大有之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>三豕俱走，鬬於谷口。白豕不勝，死於阪下。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為豕，離卦數三，故曰三豕。艮為谷，伏兌為口。兌剛魯毀折故鬬。兌，西方色白，故曰白豕。坤死艮阪，故曰死於阪下。○谷，宋元本作虎，依汲古。</p><h3 id="大有之明夷" tabindex="-1">大有之明夷 <a class="header-anchor" href="#大有之明夷" aria-label="Permalink to “大有之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>賴主之光，受德之佑。雖遭顛沛，獨不兇咎。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為主，離為光，震為德。○主，依汲古，宋元本作先。遭，依宋元本，汲古作造。</p><h3 id="大有之家人" tabindex="-1">大有之家人 <a class="header-anchor" href="#大有之家人" aria-label="Permalink to “大有之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>上義崇德，以建大福。明哲且聰，周武立功。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>通《解》。震為德、為福、為建，離為明、為哲、為聰，震為周、為武、為功。○哲、立功，從宋元本，汲古作德、作功立，非。</p><h3 id="大有之睽" tabindex="-1">大有之睽 <a class="header-anchor" href="#大有之睽" aria-label="Permalink to “大有之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>四亂不安，東西為患。身止無功，不出國城。乃得全完，賴其生福。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>兌數四，離為亂，坎險故不安。離為東，坎為西、為患，伏艮為身、為止、為國城，艮止故不出。</p><h3 id="大有之蹇" tabindex="-1">大有之蹇 <a class="header-anchor" href="#大有之蹇" aria-label="Permalink to “大有之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>金牙鐵齒，西王母子。無有患殆，涉道大利。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《大有》，此亦用《大有》象。○涉道大利，依汲古，宋元本作滅害道利。</p><h3 id="大有之解" tabindex="-1">大有之解 <a class="header-anchor" href="#大有之解" aria-label="Permalink to “大有之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>賀喜從福，日利蕃息，歡樂有得。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為喜樂、為賀、為福，伏巽為利，離為日，震為蕃息。</p><h3 id="大有之損" tabindex="-1">大有之損 <a class="header-anchor" href="#大有之損" aria-label="Permalink to “大有之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>昊天白日，照臨我國。萬民康寧，鹹賴嘉福。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮一陽在上故為天、為日，納丙，故曰昊天。昊天，夏日也。坤為我、為國，艮為光明，故曰照臨。坤為萬民，震為康寧、為嘉福。○嘉福，依宋元本，汲古作受福。</p><h3 id="大有之益" tabindex="-1">大有之益 <a class="header-anchor" href="#大有之益" aria-label="Permalink to “大有之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>左眇右盲，視暗不明。下民多孽，君失其常。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為左，伏兌為右，互大離故曰眇、曰盲、曰不明。坤為黑暗、為下、為民、為孽，震為君。</p><h3 id="大有之夬" tabindex="-1">大有之夬 <a class="header-anchor" href="#大有之夬" aria-label="Permalink to “大有之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>吾有黍粱，委積道傍。有囊服箱，運到我鄉，藏於嘉倉。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮為道，坤為委積、為囊、為箱、為鄉，坤載故曰運。坤為藏，艮為倉，又為果蓏。蓏，草實也。黍粱故為艮象。○吾有，從汲古，宋元本作吾家。囊，從宋元，汲古作架。</p><h3 id="大有之姤" tabindex="-1">大有之姤 <a class="header-anchor" href="#大有之姤" aria-label="Permalink to “大有之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>殊類異路，心不相慕。牝豕無猳，鰥無室家。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為類、為心，震為大塗，坤為牝，巽為豕，故曰牝豕。猳，牡也。坤寡故曰鰥。○牝豕，宋元本作牝猭，依汲古。</p><h3 id="大有之萃" tabindex="-1">大有之萃 <a class="header-anchor" href="#大有之萃" aria-label="Permalink to “大有之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>雀行求食，出門見鷂。顛蹶上下，幾無所處。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為雀、為求，兌為食，艮為門、為鷂，兌折故顛蹶。</p><h3 id="大有之升" tabindex="-1">大有之升 <a class="header-anchor" href="#大有之升" aria-label="Permalink to “大有之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>野有積庾，穡人駕取。不逢狼虎，暮歸其宇。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為野、為積、為庾。震為稼穡、為人，故曰穡人。艮為虎狼，艮伏故不逢。坤為莫，震為歸。○積庾，宋本作積庚，元本作種庾，依汲古。狼虎，亦依汲古，宋元本作虎狼，與下宇不韻。</p><h3 id="大有之困" tabindex="-1">大有之困 <a class="header-anchor" href="#大有之困" aria-label="Permalink to “大有之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>膚敏之德，發憤晨食。虜豹禽說，為王求福。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《觀》。○虜，依汲古，宋元本訛虎。晨，各本皆作忘，依宋元本《師》之《觀》校改。說，從宋元，淮陰伐趙禽夏說，汲古作越，非。</p><h3 id="大有之井" tabindex="-1">大有之井 <a class="header-anchor" href="#大有之井" aria-label="Permalink to “大有之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>光祀春成，陳寶雞鳴。陽明失道，不能自守，消亡為咎。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>《漢書郊祀志》：&quot;秦文公獲若石於陳倉北阪城，祠之，其神來，常以夜光輝若流星從東方來，集於祠城，其聲殷殷，若雄雉野雞夜鳴，名曰陳寶&quot;。茲雲春城，疑祠城之訛，疑原句無春字，祀成即祠城，或為光集祠城也。卦通《噬嗑》。離為光，坎為集，艮為祠城，震為陳、為鳴，本卦巽為雞。○光祀，從宋元本，汲古作光禮。禮，即集之音訛字。陳寶，宋本、汲古皆作陳項，非，依元本。</p><h3 id="大有之革" tabindex="-1">大有之革 <a class="header-anchor" href="#大有之革" aria-label="Permalink to “大有之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>左抱金玉，右得熊足。常盈不亡，獲心所欲。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為左、為玉，艮為金、為抱，兌為右，艮熊震足，坤為多，故曰常盈。坤為亡，震樂故不亡。坎為心、為欲。○艮金證。熊足即熊掌。</p><h3 id="大有之鼎" tabindex="-1">大有之鼎 <a class="header-anchor" href="#大有之鼎" aria-label="Permalink to “大有之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>履泥汙足，名困身辱。兩仇相得，身為痛瘧。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為足、為履，坤為土、為水，故曰履泥汙足。艮為名，坎陷，故名困。坤為身，坤下故辱，坤數二故曰兩。正反艮故相仇。○為痛瘧，依宋元本，汲古作其為虐。</p><h3 id="大有之震" tabindex="-1">大有之震 <a class="header-anchor" href="#大有之震" aria-label="Permalink to “大有之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>安居重遷，不去其。禾米相間，樂得常產。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為居，艮止，故安居不遷。震往，艮，艮止，故不去其。震為禾米，為樂。○，從汲古，宋元本作亶，音訛字。</p><h3 id="大有之艮" tabindex="-1">大有之艮 <a class="header-anchor" href="#大有之艮" aria-label="Permalink to “大有之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>天災所遊，兇不可居。轉徙獲福，留止憂危。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互坎為災兇，震為遊，上下卦陽在上故曰天災。艮為居，坎險，故不可居。震為徙、為福，艮止坎危。○憂危，從汲古，與居韻，宋元作危憂。</p><h3 id="大有之漸" tabindex="-1">大有之漸 <a class="header-anchor" href="#大有之漸" aria-label="Permalink to “大有之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>昧昧墨墨，不知白黑。景雲亂擾，光明隱伏。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>犬戎來攻，幽王失國。坎隱伏故曰昧墨，故不知白黑。巽為白，坎為黑、為雲，離明，故曰景雲。離為亂、為光明，坎伏艮犬，坎為幽、為失，艮為國，震為王，震伏，故曰幽王。○白黑，依宋元本，汲古作日黑。</p><h3 id="大有之歸妹" tabindex="-1">大有之歸妹 <a class="header-anchor" href="#大有之歸妹" aria-label="Permalink to “大有之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>鳧雁啞啞，以水為宅。雌雄相和，心志娛樂。得其所欲。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《鼎》。○心志，依宋元，汲古作常共。</p><h3 id="大有之豐" tabindex="-1">大有之豐 <a class="header-anchor" href="#大有之豐" aria-label="Permalink to “大有之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>長生無極，子孫千億。柏柱載梁，堅固不傾。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為長生、為子，伏艮為孫。震為千億、為柏柱、為載、為梁，伏艮為堅固。○梁，從汲古，宋元本作器。</p><h3 id="大有之旅" tabindex="-1">大有之旅 <a class="header-anchor" href="#大有之旅" aria-label="Permalink to “大有之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>麒麟鳳凰，善政得祥。陰陽和調，國無災殃。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>離為文明，故曰麟鳳。卦一陰從一陽，二陰從二陽，故曰和調。</p><h3 id="大有之巽" tabindex="-1">大有之巽 <a class="header-anchor" href="#大有之巽" aria-label="Permalink to “大有之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>天之奧隅，堯舜所居。可以存身，保我室家。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏艮為天，震為帝，故曰堯舜。艮為居、為身、為室家、為保。全用旁通。○室家，從宋元，汲古作家室，非。家，音姑，與居韻。</p><h3 id="大有之兌" tabindex="-1">大有之兌 <a class="header-anchor" href="#大有之兌" aria-label="Permalink to “大有之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>配合相迎，利之四鄰。昏以為期，與福笑喜。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>兌昧為昏，震為福、為笑喜。迎鄰為韻，鄰，音靈。</p><h3 id="大有之渙" tabindex="-1">大有之渙 <a class="header-anchor" href="#大有之渙" aria-label="Permalink to “大有之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>砥德礪材，果當成周。拜受大命，對為齊侯。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為德、為材，艮石，故曰砥礪。震為周，艮為拜，巽為命、為齊。</p><h3 id="大有之節" tabindex="-1">大有之節 <a class="header-anchor" href="#大有之節" aria-label="Permalink to “大有之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>與福俱坐，蓄水備火，終無災禍。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為福，艮為坐，坎水艮火，坎為積蓄、為災禍。○宋元本多&quot;思患預防&quot;四字為第三句，依汲古。</p><h3 id="大有之中孚" tabindex="-1">大有之中孚 <a class="header-anchor" href="#大有之中孚" aria-label="Permalink to “大有之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>晨昏潛處，候時煦煦。卒逢白日，為世榮主。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為晨，兌為昧、為昏，巽為潛，艮為待、為時，震為煦。煦，和也。巽為白，艮為日，震為主、為榮。○晨，元本作畏，依宋本、汲古。候時煦煦，宋元本作候明昭昭，茲從汲古。煦主為韻。</p><h3 id="大有之小過" tabindex="-1">大有之小過 <a class="header-anchor" href="#大有之小過" aria-label="Permalink to “大有之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>視日再光，與天相望。長生歡悅，與福為多。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為日、為光、為望、為天，巽長震生，震歡悅為福、為多也。○再，從汲古，宋元本作載。多，從宋元本，汲古作兄。與，從汲古，宋元作以。○艮為天證。</p><h3 id="大有之既濟" tabindex="-1">大有之既濟 <a class="header-anchor" href="#大有之既濟" aria-label="Permalink to “大有之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>大頭明目，載受嘉福。三雀飛來，與祿相觸。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎為大首，離為明目，震為載、為嘉福。離為鳥，卦數三，故曰三雀飛來。震為飛、為祿。除坎離外，皆用半象。○載受嘉福，從宋元本，汲古作再受喜福。三，從宋元本，汲古作二。觸，從汲古，宋元訛單。</p><h3 id="大有之未濟" tabindex="-1">大有之未濟 <a class="header-anchor" href="#大有之未濟" aria-label="Permalink to “大有之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>楩生荊山，命屬輸班。袍衣剝脫，夏熱冬寒。立成枯槁，眾人莫憐。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《既濟》。楩，汲古訛梗，依宋元本。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
